(3930620, 558976, 61818, '<td valign="top">I like what you were going for here, but I think it would have worked better were the top portion equally as noise free as the bottom and also if the color had settled nicely to the bottom across the board.  There''s some beautiful symmetry here which these minor imperfections really tear apart.</td>', 'I like what you were going for here, but I think it would have worked better were the top portion equally as noise free as the bottom and also if the color had settled nicely to the bottom across the board.  There''s some beautiful symmetry here which these minor imperfections really tear apart.', '2007-07-24 00:27:01.000000', NULL, 1),
(3930621, 559049, 48228, '<td valign="top">A very pleasing sodt white on white rhythm image here.....</td>', 'A very pleasing sodt white on white rhythm image here.....', '2007-07-24 00:27:09.000000', NULL, 1),
