(3931374, 558845, 67258, '<td valign="top">A very strong composition with good b&amp;w conversion.  i imagine this would look good framed in a plain balck frame on the wall.</td>', 'A very strong composition with good b&w conversion.  i imagine this would look good framed in a plain balck frame on the wall.', '2007-07-24 08:57:49.000000', NULL, 1),
(3931375, 558452, 73235, '<td valign="top">I like the composition. the 2 branches in the upper right corner are distracting. Good didea to break the pattern in the lower left corner. nice strong tones.</td>', 'I like the composition. the 2 branches in the upper right corner are distracting. Good didea to break the pattern in the lower left corner. nice strong tones.', '2007-07-24 08:58:54.000000', NULL, 1),
(3931379, 556378, 67258, '<td valign="top">Spot on for the challenge. Wonderful organic curves and shapes - mineral or vegetable?  Either way I love the texture, composition and colour; excellent work.</td>', 'Spot on for the challenge. Wonderful organic curves and shapes - mineral or vegetable?  Either way I love the texture, composition and colour; excellent work.', '2007-07-24 09:01:19.000000', NULL, 1),
