(3931575, 557863, 65858, '<td valign="top">Interesting shot.  Technically very nice!</td>', 'Interesting shot.  Technically very nice!', '2007-07-24 10:17:43.000000', NULL, 1),
(3931577, 559008, 65858, '<td valign="top">Intriguing!  I can''t wait to find out what it is, but the texture and slight color variation are fantastic!  Perfectly composed. 9!</td>', 'Intriguing!  I can''t wait to find out what it is, but the texture and slight color variation are fantastic!  Perfectly composed. 9!', '2007-07-24 10:19:13.000000', NULL, 1),
