(3931616, 556763, 73235, '<td valign="top">One of my favorites, lighting, composition, lines, everything just right.10</td>', 'One of my favorites, lighting, composition, lines, everything just right.10', '2007-07-24 10:33:55.000000', NULL, 1),
(3931621, 559230, 73235, '<td valign="top">while this is a good picture of a horse, it does not support rhythm to me.</td>', 'while this is a good picture of a horse, it does not support rhythm to me.', '2007-07-24 10:36:10.000000', NULL, 1),
(3931626, 559042, 73235, '<td valign="top">great capture. the sky is not really adding anything (featureless). I know it''s easy to say without beeing there: a little lower angle to hide the tree tops and a tighter crop to not show so much of the sly would make a much much strong er picture. You have a very good eye to see this rhythm.</td>', 'great capture. the sky is not really adding anything (featureless). I know it''s easy to say without beeing there: a little lower angle to hide the tree tops and a tighter crop to not show so much of the sly would make a much much strong er picture. You have a very good eye to see this rhythm.', '2007-07-24 10:38:54.000000', NULL, 1),
(3931628, 558971, 61818, '<td valign="top">I imagine you are taking a beating on this one.  Tree bark could work for this challenge.  Perhaps losing the blownout portion on the right of the shot would better focus attention on the patterns in your subject.  Also, the subject itself needs to be in good focus without a heavy reliance on unsharp.  Further, I think you could really increase the impact (and thus the ''wow'' factor) by presenting this in black and white.  It might make the most out of the paterns/rhythm in the bark by highlighting the contrasts of light and shapes contained within.</td>', 'I imagine you are taking a beating on this one.  Tree bark could work for this challenge.  Perhaps losing the blownout portion on the right of the shot would better focus attention on the patterns in your subject.  Also, the subject itself needs to be in good focus without a heavy reliance on unsharp.  Further, I think you could really increase the impact (and thus the ''wow'' factor) by presenting this in black and white.  It might make the most out of the paterns/rhythm in the bark by highlighting the contrasts of light and shapes contained within.', '2007-07-24 10:39:07.000000', NULL, 1),
(3931721, 559168, 14476, '<td valign="top">Unfortunate title, GREAT image.</td>', 'Unfortunate title, GREAT image.', '2007-07-24 11:37:10.000000', NULL, 1),
(3931723, 558868, 14476, '<td valign="top">Oh, looks like the Seine.  Nice.</td>', 'Oh, looks like the Seine.  Nice.', '2007-07-24 11:41:23.000000', NULL, 1),
(3932015, 559230, 62318, '<td valign="top">Hopefully people will understand the canter section. Good idea for the challenge.</td>', 'Hopefully people will understand the canter section. Good idea for the challenge.', '2007-07-24 13:27:13.000000', NULL, 1),
(3932021, 558336, 62318, '<td valign="top">Well, I haven''t gone through all the images yet, but I have a feeling this is the best of the bunch. Solid 9 in my book, maybe a half stop more depth to make it a 10. Terrific textures and lines.</td>', 'Well, I haven''t gone through all the images yet, but I have a feeling this is the best of the bunch. Solid 9 in my book, maybe a half stop more depth to make it a 10. Terrific textures and lines.', '2007-07-24 13:30:26.000000', NULL, 1),
