(3940407, 559074, 42100, '<td valign="top">A graceful flowing rhythm...very beautiful color and light.  Great abstract!</td>', 'A graceful flowing rhythm...very beautiful color and light.  Great abstract!', '2007-07-26 17:33:35.000000', NULL, 1),
(3940425, 558412, 42100, '<td valign="top">I''m sensing a more upbeat tempo with this rhythm...fantastic macro!  The color combo is outstanding and the circle bokeh are like little dancing faeries.</td>', 'I''m sensing a more upbeat tempo with this rhythm...fantastic macro!  The color combo is outstanding and the circle bokeh are like little dancing faeries.', '2007-07-26 17:36:09.000000', NULL, 1),
