(3942054, 557863, 74533, '<td valign="top">I love the out of focus and muted colours of the background.  A good portrait photo.</td>', 'I love the out of focus and muted colours of the background.  A good portrait photo.', '2007-07-27 07:14:19.000000', NULL, 1),
(3942055, 556132, 74533, '<td valign="top">Beautiful colours.  Soft and delicate.</td>', 'Beautiful colours.  Soft and delicate.', '2007-07-27 07:14:49.000000', NULL, 1),
