INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3942065, 558954, 74533, '<td valign="top">I really like the colours that you have brought out in this photo.  The warmth in the timber is lovely against the aged timber.</td>', 'I really like the colours that you have brought out in this photo.  The warmth in the timber is lovely against the aged timber.', '2007-07-27 07:21:36.000000', NULL, 1),
(3942067, 559075, 74533, '<td valign="top">Is he peeking out from behind the flower?  Beautiful contrast between the leaves and the crisp white of the flower.</td>', 'Is he peeking out from behind the flower?  Beautiful contrast between the leaves and the crisp white of the flower.', '2007-07-27 07:23:32.000000', NULL, 1),
(3942068, 558838, 74533, '<td valign="top">Very abstract and clean.  Nice contrast.</td>', 'Very abstract and clean.  Nice contrast.', '2007-07-27 07:24:00.000000', NULL, 1),
(3942070, 559088, 74533, '<td valign="top">How interesting!  A little grey.  I bit more contrast may have been better.  Where did you take the photo?</td>', 'How interesting!  A little grey.  I bit more contrast may have been better.  Where did you take the photo?', '2007-07-27 07:25:13.000000', NULL, 1),
(3942071, 558420, 74533, '<td valign="top">Very interesting.  Makes me want to know about the photo.  I like the difference of the textures and the warmness of colours.</td>', 'Very interesting.  Makes me want to know about the photo.  I like the difference of the textures and the warmness of colours.', '2007-07-27 07:26:50.000000', NULL, 1),
(3942073, 556433, 74533, '<td valign="top">I like this photo but it also confuses me.  I can''t figure it out.  It is very abstract. Looks like a spiral staircase but tell us later what and how.</td>', 'I like this photo but it also confuses me.  I can''t figure it out.  It is very abstract. Looks like a spiral staircase but tell us later what and how.', '2007-07-27 07:28:48.000000', NULL, 1),
(3942075, 559214, 74533, '<td valign="top">Good but not really interesting.</td>', 'Good but not really interesting.', '2007-07-27 07:29:30.000000', NULL, 1),
(3942077, 559008, 74533, '<td valign="top">Ooh, I like this.  Great colour and texture.  The shapes are a lovely surprise too.</td>', 'Ooh, I like this.  Great colour and texture.  The shapes are a lovely surprise too.', '2007-07-27 07:30:43.000000', NULL, 1),
(3942079, 558336, 74533, '<td valign="top">What a nice contrast in colours and textures and shape.  A very good macro.</td>', 'What a nice contrast in colours and textures and shape.  A very good macro.', '2007-07-27 07:31:22.000000', NULL, 1),
(3942080, 559268, 74533, '<td valign="top">This photo has a lovely light, airy and fresh feel to it.  The subject is clear and the out of focus background make a beautiful backdrop.  Well done.</td>', 'This photo has a lovely light, airy and fresh feel to it.  The subject is clear and the out of focus background make a beautiful backdrop.  Well done.', '2007-07-27 07:32:30.000000', NULL, 1),
(3942081, 559216, 74533, '<td valign="top">Great perspective.  Love the monotone colour treatment.  Very appropriate to the photo.</td>', 'Great perspective.  Love the monotone colour treatment.  Very appropriate to the photo.', '2007-07-27 07:33:25.000000', NULL, 1),
(3942083, 558531, 74533, '<td valign="top">A good idea.  I would personally like to have seen 1/3 of the left hand side of the photo cropped out and a tighter crop on the 2/3 on the right.  Then a bit more colour contrast added.</td>', 'A good idea.  I would personally like to have seen 1/3 of the left hand side of the photo cropped out and a tighter crop on the 2/3 on the right.  Then a bit more colour contrast added.', '2007-07-27 07:35:04.000000', NULL, 1),
(3942084, 558878, 74533, '<td valign="top">Wow looks like fun!!</td>', 'Wow looks like fun!!', '2007-07-27 07:36:04.000000', NULL, 1),
(3942087, 558847, 74533, '<td valign="top">Nice repetition of colour and shape.  I think that the flash on the top right corner is not great.  Maybe you could have cropped it out.  A slight saturation of colour might have added impact.</td>', 'Nice repetition of colour and shape.  I think that the flash on the top right corner is not great.  Maybe you could have cropped it out.  A slight saturation of colour might have added impact.', '2007-07-27 07:38:14.000000', NULL, 1),
