(3944463, 559223, 30982, '<td valign="top">Good composition and well timed to get the fire, the smoke, and the one guy''s eyes closed.  I like the synchronicity of the shapes of the arms.</td>', 'Good composition and well timed to get the fire, the smoke, and the one guy''s eyes closed.  I like the synchronicity of the shapes of the arms.', '2007-07-28 06:44:54.000000', NULL, 1),
(3944466, 559168, 30982, '<td valign="top">Excellent detail and light - a kind of symphonic rhythm.</td>', 'Excellent detail and light - a kind of symphonic rhythm.', '2007-07-28 06:46:32.000000', NULL, 1),
