(3944673, 558201, 66597, '<td valign="top">Hi Daniel - can''t vote since I know it is yours :-) but I will say it shows very well.</td>', 'Hi Daniel - can''t vote since I know it is yours :-) but I will say it shows very well.', '2007-07-28 10:45:10.000000', NULL, 1),
(3944675, 558236, 66597, '<td valign="top">Nice exposure but color temp looks overly warm on this one.</td>', 'Nice exposure but color temp looks overly warm on this one.', '2007-07-28 10:45:41.000000', NULL, 1),
(3944676, 559019, 66597, '<td valign="top">This is a beautiful still life. Not sure it exactly fits rhythm, but I certainly like the patterns and b/w conversion.</td>', 'This is a beautiful still life. Not sure it exactly fits rhythm, but I certainly like the patterns and b/w conversion.', '2007-07-28 10:46:17.000000', NULL, 1),
