(3947345, 558870, 13207, '<td valign="top">Great shot - I love how the snails are heading in different directions - the color and clarity of this shot, as well, is beautiful.</td>', 'Great shot - I love how the snails are heading in different directions - the color and clarity of this shot, as well, is beautiful.', '2007-07-29 22:09:42.000000', NULL, 1),
(3947349, 558991, 13207, '<td valign="top">This is one of my favourites from this challenge - I love the dof.  Great job!</td>', 'This is one of my favourites from this challenge - I love the dof.  Great job!', '2007-07-29 22:10:18.000000', NULL, 1),
(3947352, 559177, 13207, '<td valign="top">I love this concept, one of the more original entries in this challenge.</td>', 'I love this concept, one of the more original entries in this challenge.', '2007-07-29 22:11:13.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3947355, 559008, 13207, '<td valign="top">Beautiful - I can''t even begin to guess what this is, but the flow of the lines, along with the light and shadows really make for an excellent shot.</td>', 'Beautiful - I can''t even begin to guess what this is, but the flow of the lines, along with the light and shadows really make for an excellent shot.', '2007-07-29 22:11:53.000000', NULL, 1),
(3947356, 558898, 13207, '<td valign="top">Very nice, clean lines - I like the yellow against the blue background</td>', 'Very nice, clean lines - I like the yellow against the blue background', '2007-07-29 22:12:34.000000', NULL, 1),
(3947507, 557863, 66384, '<td valign="top">This is such a beautiful picture, and while there is no movement here, there I can see the rhythm of these lives. It''s going in my favorites. 10</td>', 'This is such a beautiful picture, and while there is no movement here, there I can see the rhythm of these lives. It''s going in my favorites. 10', '2007-07-29 23:10:08.000000', NULL, 1),
(3947615, 559268, 58430, '<td valign="top">Nice bokeh, love the golden tones contrasting with the blue sky.  Perfect focus, nice composition.</td>', 'Nice bokeh, love the golden tones contrasting with the blue sky.  Perfect focus, nice composition.', '2007-07-29 23:42:33.000000', NULL, 1),
(3947618, 558838, 58430, '<td valign="top">Like the B&amp;W.  Nice lines.  Like how it seems to ripple to the left and fadeout.</td>', 'Like the B&W.  Nice lines.  Like how it seems to ripple to the left and fadeout.', '2007-07-29 23:44:16.000000', NULL, 1),
(3947619, 559094, 67697, '<td valign="top">Nice play with light and shadow.</td>', 'Nice play with light and shadow.', '2007-07-29 23:44:33.000000', NULL, 1),
(3947623, 559237, 67697, '<td valign="top">I like how the perspective leads at a slight angle into the background.</td>', 'I like how the perspective leads at a slight angle into the background.', '2007-07-29 23:46:13.000000', NULL, 1),
(3947624, 559268, 67697, '<td valign="top">Great closeup.  Love the background.</td>', 'Great closeup.  Love the background.', '2007-07-29 23:46:29.000000', NULL, 1),
(3947627, 558094, 58430, '<td valign="top">I like the colors and the skyline in the background and how the center of the pic is the triangular building. Seems a tad oversharpened.</td>', 'I like the colors and the skyline in the background and how the center of the pic is the triangular building. Seems a tad oversharpened.', '2007-07-29 23:47:35.000000', NULL, 1),
(3947629, 559283, 67697, '<td valign="top">Love how it is mostly pairs of people.  Nice black and white.</td>', 'Love how it is mostly pairs of people.  Nice black and white.', '2007-07-29 23:47:42.000000', NULL, 1),
(3947634, 558869, 58430, '<td valign="top">What a great picture.  Love the composition and bright colors.  I''d like a touch more sky on the far right</td>', 'What a great picture.  Love the composition and bright colors.  I''d like a touch more sky on the far right', '2007-07-29 23:49:09.000000', NULL, 1),
(3947639, 558876, 58430, '<td valign="top">I wish this pic were larger.  Very nice idea.</td>', 'I wish this pic were larger.  Very nice idea.', '2007-07-29 23:50:18.000000', NULL, 1),
(3947648, 558886, 58430, '<td valign="top">I wish the ladybug were sharper and the background were a better color.  But I like the designs in the leaf and the idea.</td>', 'I wish the ladybug were sharper and the background were a better color.  But I like the designs in the leaf and the idea.', '2007-07-29 23:52:39.000000', NULL, 1),
(3947650, 558967, 58430, '<td valign="top">I think the square crop works very well here but the subject matter is not very exciting.</td>', 'I think the square crop works very well here but the subject matter is not very exciting.', '2007-07-29 23:53:35.000000', NULL, 1),
(3947653, 559115, 58430, '<td valign="top">Very nice textures here.</td>', 'Very nice textures here.', '2007-07-29 23:54:18.000000', NULL, 1),
(3947656, 558251, 43400, '<td valign="top">interesting macro (of finger?). Well capture and unique</td>', 'interesting macro (of finger?). Well capture and unique', '2007-07-29 23:55:22.000000', NULL, 1),
(3947659, 558420, 58430, '<td valign="top">Great composition and lines and how the lines are very symmetric from top to bottom.  Love the rusty look.  The border works very well here.</td>', 'Great composition and lines and how the lines are very symmetric from top to bottom.  Love the rusty look.  The border works very well here.', '2007-07-29 23:55:39.000000', NULL, 1),
(3947661, 558412, 58430, '<td valign="top">Cool textures going on here and very nice composition.</td>', 'Cool textures going on here and very nice composition.', '2007-07-29 23:56:16.000000', NULL, 1),
(3947664, 559008, 58430, '<td valign="top">Awesome sense of rhythm and motion. I just love the rusty tones changing into the greys.</td>', 'Awesome sense of rhythm and motion. I just love the rusty tones changing into the greys.', '2007-07-29 23:57:00.000000', NULL, 1),
(3947667, 558968, 58430, '<td valign="top">Nice macro but I wonder if it would look better cropping and focusing in on the  top part of the feather.</td>', 'Nice macro but I wonder if it would look better cropping and focusing in on the  top part of the feather.', '2007-07-29 23:57:53.000000', NULL, 1),
(3947669, 559277, 58430, '<td valign="top">Great sky.  Just love the colors going on.  I can almost feel the rocking of the boats.</td>', 'Great sky.  Just love the colors going on.  I can almost feel the rocking of the boats.', '2007-07-29 23:58:51.000000', NULL, 1),
(3947670, 558963, 43400, '<td valign="top">i would have chosen a different angle and without the flash, but it''s an interesting image--heck you can even see the dust (in a good way)- it adds character.</td>', 'i would have chosen a different angle and without the flash, but it''s an interesting image--heck you can even see the dust (in a good way)- it adds character.', '2007-07-29 23:58:55.000000', NULL, 1),
(3947676, 559240, 58430, '<td valign="top">Love the water but the foliage seems oof.  Might be more dramatic if cropped to only have the motion of the water.</td>', 'Love the water but the foliage seems oof.  Might be more dramatic if cropped to only have the motion of the water.', '2007-07-29 23:59:51.000000', NULL, 1),
(3947677, 558748, 58430, '<td valign="top">Cute idea but the lighting seems a tad harsh.</td>', 'Cute idea but the lighting seems a tad harsh.', '2007-07-30 00:00:20.000000', NULL, 1),
(3947680, 559075, 58430, '<td valign="top">Nice pond shot.  Seems a tad overexposed because the details in the flower are lost.</td>', 'Nice pond shot.  Seems a tad overexposed because the details in the flower are lost.', '2007-07-30 00:01:05.000000', NULL, 1),
(3947686, 559114, 58430, '<td valign="top">Love how the person in the front is well lit and totally in focus.  I also like the square crop and the color of the background.</td>', 'Love how the person in the front is well lit and totally in focus.  I also like the square crop and the color of the background.', '2007-07-30 00:02:33.000000', NULL, 1),
(3947694, 558440, 58430, '<td valign="top">I''d like to see more contrast(?) to see more dramatic detail in the wood but I really like the sense of motion and rhythm here.</td>', 'I''d like to see more contrast(?) to see more dramatic detail in the wood but I really like the sense of motion and rhythm here.', '2007-07-30 00:03:57.000000', NULL, 1),
(3947700, 559223, 58430, '<td valign="top">This does not really speak rhythm to me.  I wish I could see all of the gun and not just the stock.</td>', 'This does not really speak rhythm to me.  I wish I could see all of the gun and not just the stock.', '2007-07-30 00:05:47.000000', NULL, 1),
(3947702, 558664, 15407, '<td valign="top">A tough one to do with this lighting but the halos on the horizon distrac. I wonder about the star trails which are great! yet I wonder why what appears to be stars tht are not producing any significnt star trails ~ could it be dead pixels on your sensor?</td>', 'A tough one to do with this lighting but the halos on the horizon distrac. I wonder about the star trails which are great! yet I wonder why what appears to be stars tht are not producing any significnt star trails ~ could it be dead pixels on your sensor?', '2007-07-30 00:05:56.000000', NULL, 1),
(3947704, 559052, 58430, '<td valign="top">Wow, really cool night shot.  I wish I could see this larger...I bet the detail is amazing.  Great composition, great colors, and I love the reflection in the water.</td>', 'Wow, really cool night shot.  I wish I could see this larger...I bet the detail is amazing.  Great composition, great colors, and I love the reflection in the water.', '2007-07-30 00:07:17.000000', NULL, 1),
(3947706, 559259, 43400, '<td valign="top">over-processed or not, i think it''s very appealing. i like the simle subject/composition and tones.</td>', 'over-processed or not, i think it''s very appealing. i like the simle subject/composition and tones.', '2007-07-30 00:07:24.000000', NULL, 1),
(3947707, 559147, 58430, '<td valign="top">This definitely shows rhythm but is not very exciting.</td>', 'This definitely shows rhythm but is not very exciting.', '2007-07-30 00:07:54.000000', NULL, 1),
(3947709, 558555, 15407, '<td valign="top">A selective saturation on the guitar strings in a gradient of ''blues'' would have gotten 2 more point on this from me...(6)</td>', 'A selective saturation on the guitar strings in a gradient of ''blues'' would have gotten 2 more point on this from me...(6)', '2007-07-30 00:08:33.000000', NULL, 1),
(3947711, 559268, 43400, '<td valign="top">excellent tones and detail. the colors/tones are perfecto</td>', 'excellent tones and detail. the colors/tones are perfecto', '2007-07-30 00:08:50.000000', NULL, 1),
(3947712, 557431, 58430, '<td valign="top">Love this.  The black background makes the colors pop.  Real sense of rhythm.  Very nice diagonal lines.</td>', 'Love this.  The black background makes the colors pop.  Real sense of rhythm.  Very nice diagonal lines.', '2007-07-30 00:09:15.000000', NULL, 1),
(3947713, 558886, 43400, '<td valign="top">interesting image, but it''s hard to read "rhythm" here personally.</td>', 'interesting image, but it''s hard to read "rhythm" here personally.', '2007-07-30 00:10:15.000000', NULL, 1),
(3947717, 559129, 58430, '<td valign="top">Very cool picture.  Love the painting with light and the blue tones.  Not sure this speaks of rhythm to me but this is a very good image.</td>', 'Very cool picture.  Love the painting with light and the blue tones.  Not sure this speaks of rhythm to me but this is a very good image.', '2007-07-30 00:10:58.000000', NULL, 1),
(3947719, 557427, 43400, '<td valign="top">beautiful--i''m curious to know the camera/lense type used because the details and exposure are incredible.--9</td>', 'beautiful--i''m curious to know the camera/lense type used because the details and exposure are incredible.--9', '2007-07-30 00:12:07.000000', NULL, 1),
(3947720, 558555, 58430, '<td valign="top">Sorry about the guitar ;-)  Good idea.  Background colors don''t seem to enhance the guitar but detract from it.</td>', 'Sorry about the guitar ;-)  Good idea.  Background colors don''t seem to enhance the guitar but detract from it.', '2007-07-30 00:12:11.000000', NULL, 1),
(3947731, 559160, 58430, '<td valign="top">Seems to be too much sky.  I''d like to really emphasize the headstones and have  them be in super sharp focus with less black sky.  There seems to be a strange black blob in the middle of the picture to the right of the headstones like something was cloned out and the black seems noisy.</td>', 'Seems to be too much sky.  I''d like to really emphasize the headstones and have  them be in super sharp focus with less black sky.  There seems to be a strange black blob in the middle of the picture to the right of the headstones like something was cloned out and the black seems noisy.', '2007-07-30 00:15:23.000000', NULL, 1),
(3947736, 559204, 58430, '<td valign="top">Nice use the the rule of thirds.  Great detail in the shell.  I wonder if this would be better with no water because the movement of the water detracts a bit from the shell in the top right corner.</td>', 'Nice use the the rule of thirds.  Great detail in the shell.  I wonder if this would be better with no water because the movement of the water detracts a bit from the shell in the top right corner.', '2007-07-30 00:16:53.000000', NULL, 1),
(3947739, 559237, 43400, '<td valign="top">there''s plenty of rhythm here and it works well--it just does''nt have a "WOW" feeling to it. Perhaps if you chose a different tone or hue to it, or even make it a bit darker to add a sense of mystery--it would problably add more visual impact. good potential here.</td>', 'there''s plenty of rhythm here and it works well--it just does''nt have a "WOW" feeling to it. Perhaps if you chose a different tone or hue to it, or even make it a bit darker to add a sense of mystery--it would problably add more visual impact. good potential here.', '2007-07-30 00:17:21.000000', NULL, 1),
(3947740, 558971, 58430, '<td valign="top">Wish this were more in focus and the background is not really enhancing the tree trunk but is a bit too bright and draws your eye away.</td>', 'Wish this were more in focus and the background is not really enhancing the tree trunk but is a bit too bright and draws your eye away.', '2007-07-30 00:17:44.000000', NULL, 1),
(3947746, 557018, 58430, '<td valign="top">Can''t quite figure out what this is.  The pp is distracting but the image definitely shows rhythm.</td>', 'Can''t quite figure out what this is.  The pp is distracting but the image definitely shows rhythm.', '2007-07-30 00:18:54.000000', NULL, 1),
(3947749, 557865, 43400, '<td valign="top">very interesting. before i scrolled down to your title--i thought it was fur/animal hair in absract form--nicely capture and appealing.</td>', 'very interesting. before i scrolled down to your title--i thought it was fur/animal hair in absract form--nicely capture and appealing.', '2007-07-30 00:19:32.000000', NULL, 1),
(3947754, 559243, 58430, '<td valign="top">Very cool abstract image.  Nice contrast with the lights and darks.  Like the sense of movement and rhythm.</td>', 'Very cool abstract image.  Nice contrast with the lights and darks.  Like the sense of movement and rhythm.', '2007-07-30 00:20:29.000000', NULL, 1),
(3947756, 559262, 58430, '<td valign="top">Really like the idea but I wish this were in focus with more detail.</td>', 'Really like the idea but I wish this were in focus with more detail.', '2007-07-30 00:21:08.000000', NULL, 1),
(3947758, 559221, 58430, '<td valign="top">This feels so 80''s ;-)  Not very exciting to look at.</td>', 'This feels so 80''s ;-)  Not very exciting to look at.', '2007-07-30 00:21:50.000000', NULL, 1),
(3947761, 558442, 58430, '<td valign="top">Love the colors and the 3D effect. I wish this were rotated a touch to make it more symmetric.</td>', 'Love the colors and the 3D effect. I wish this were rotated a touch to make it more symmetric.', '2007-07-30 00:22:51.000000', NULL, 1),
(3947767, 559180, 58430, '<td valign="top">Scary pov for your camera!  I wish it were not so hazy and there was more detail in the background.</td>', 'Scary pov for your camera!  I wish it were not so hazy and there was more detail in the background.', '2007-07-30 00:24:33.000000', NULL, 1),
(3947769, 558825, 58430, '<td valign="top">Very nice lines.  Cool image!</td>', 'Very nice lines.  Cool image!', '2007-07-30 00:24:51.000000', NULL, 1),
(3947776, 558741, 58430, '<td valign="top">The lines in this image draw your eye to the lower left but then I am disappointed because the lower left corner does not fit...it takes away from the rhythm of the water.</td>', 'The lines in this image draw your eye to the lower left but then I am disappointed because the lower left corner does not fit...it takes away from the rhythm of the water.', '2007-07-30 00:26:33.000000', NULL, 1),
(3947777, 559279, 7485, '<td valign="top">The multicolored paper shots are so tired on DPC that they have to hit everything just right. Well, yours does! The fine texture (never easy at 640!), deep DOF, full tonal range, good composition, and of course the colors.</td>', 'The multicolored paper shots are so tired on DPC that they have to hit everything just right. Well, yours does! The fine texture (never easy at 640!), deep DOF, full tonal range, good composition, and of course the colors.', '2007-07-30 00:26:49.000000', NULL, 1),
(3947779, 558204, 58430, '<td valign="top">Love the B&amp;W.  Love the motion.  Crop is too tight for the upper right corner.  Very nice image.</td>', 'Love the B&W.  Love the motion.  Crop is too tight for the upper right corner.  Very nice image.', '2007-07-30 00:27:17.000000', NULL, 1),
(3947785, 559072, 58430, '<td valign="top">Cool pattern.  Like how the top third is oof, the middle third is in focus and the bottom third is oof again.  Like the sense of motion to the right and from the top.</td>', 'Cool pattern.  Like how the top third is oof, the middle third is in focus and the bottom third is oof again.  Like the sense of motion to the right and from the top.', '2007-07-30 00:28:54.000000', NULL, 1),
(3947787, 559181, 58430, '<td valign="top">Interesting pov.  I wonder of it would be better without the bridge in the picture and rotated slightly to the right.</td>', 'Interesting pov.  I wonder of it would be better without the bridge in the picture and rotated slightly to the right.', '2007-07-30 00:29:58.000000', NULL, 1),
(3947789, 559168, 58430, '<td valign="top">Nice macro. Interesting subject. Love the use of B&amp;W.</td>', 'Nice macro. Interesting subject. Love the use of B&W.', '2007-07-30 00:30:28.000000', NULL, 1),
(3947792, 559177, 58430, '<td valign="top">Would love to see this in color and the tomatoes precisely centered.  Very nice idea and tons of potential but the B&amp;W does not work for me.</td>', 'Would love to see this in color and the tomatoes precisely centered.  Very nice idea and tons of potential but the B&W does not work for me.', '2007-07-30 00:31:42.000000', NULL, 1),
(3947800, 558531, 58430, '<td valign="top">This seems either oversharpened or oof...I can''t decide which one.  <br/> <br/>This might be better if you could zoom in to have the ducks fill more of the frame and crop so the subject is not in the middle of the picture but in the bottom third.</td>', 'This seems either oversharpened or oof...I can''t decide which one.   This might be better if you could zoom in to have the ducks fill more of the frame and crop so the subject is not in the middle of the picture but in the bottom third.', '2007-07-30 00:34:31.000000', NULL, 1),
(3947808, 558963, 39349, '<td valign="top">Couple of things about this shot to make it better, either really go for the off angle approach or try and get your leading lines level. Your flash really blew out the foreground keys. There are a couple of ways around this, use a tripod or set the camera on the piano, do not use flash but set your shutter speed and aperture to expose this without your flash. Low aperture and longer shutter speeds will produce some great effects. Finally, the dust on the keys isn''t really doing anything for your subject. Hope this helps.</td>', 'Couple of things about this shot to make it better, either really go for the off angle approach or try and get your leading lines level. Your flash really blew out the foreground keys. There are a couple of ways around this, use a tripod or set the camera on the piano, do not use flash but set your shutter speed and aperture to expose this without your flash. Low aperture and longer shutter speeds will produce some great effects. Finally, the dust on the keys isn''t really doing anything for your subject. Hope this helps.', '2007-07-30 00:36:18.000000', NULL, 1),
(3947815, 559262, 39349, '<td valign="top">Love the tones and your perspective really works here but it''s very out of focus. You can eliminate this by using a tripod and or setting the camera on a steady surface while shooting. If you were going for a soft look in this photo I don''t really see how it works here. Finally a little shift to straighten out the bottles so they are level would help this out a lot.</td>', 'Love the tones and your perspective really works here but it''s very out of focus. You can eliminate this by using a tripod and or setting the camera on a steady surface while shooting. If you were going for a soft look in this photo I don''t really see how it works here. Finally a little shift to straighten out the bottles so they are level would help this out a lot.', '2007-07-30 00:38:32.000000', NULL, 1),
(3947818, 559283, 30982, '<td valign="top">Bold, staccato rhythms.  Very nice.</td>', 'Bold, staccato rhythms.  Very nice.', '2007-07-30 00:40:43.000000', NULL, 1),
(3947819, 558220, 39349, '<td valign="top">Not sure about this shot, I think what''s hurting it the most is that there is no central subject. My eye keeps bouncing around trying to find something to land on but there''s nothing drawing it in. The clear CD is distracting with the reflection in the upper right and overall the tones in this shot are not very flattering. Perhaps a different angle on the spool of disks would yield a better result?</td>', 'Not sure about this shot, I think what''s hurting it the most is that there is no central subject. My eye keeps bouncing around trying to find something to land on but there''s nothing drawing it in. The clear CD is distracting with the reflection in the upper right and overall the tones in this shot are not very flattering. Perhaps a different angle on the spool of disks would yield a better result?', '2007-07-30 00:40:47.000000', NULL, 1),
(3947821, 559283, 58430, '<td valign="top">This is a nice idea but seems too busy.  I''d love to see a crop where the 2 main people were the only subjects.  I think it would be more dramatic and more effective.</td>', 'This is a nice idea but seems too busy.  I''d love to see a crop where the 2 main people were the only subjects.  I think it would be more dramatic and more effective.', '2007-07-30 00:42:02.000000', NULL, 1),
(3947823, 559220, 58430, '<td valign="top">This shows rhythm but is not very interesting to look at.</td>', 'This shows rhythm but is not very interesting to look at.', '2007-07-30 00:42:59.000000', NULL, 1),
(3947830, 558857, 58430, '<td valign="top">Cool location and very interesting how it appears that there is a light in the middle of nowhere.  This would be more effective if the horizon were level and the sky not so washed out.</td>', 'Cool location and very interesting how it appears that there is a light in the middle of nowhere.  This would be more effective if the horizon were level and the sky not so washed out.', '2007-07-30 00:44:22.000000', NULL, 1),
(3947832, 558361, 30982, '<td valign="top">Sandy?  Or maybe Theresa?  Very pleasing composition and I like the gentle sky.</td>', 'Sandy?  Or maybe Theresa?  Very pleasing composition and I like the gentle sky.', '2007-07-30 00:44:49.000000', NULL, 1),
(3947840, 558963, 58430, '<td valign="top">I get the idea but the foreground is too washed out and the piano should have been dusted.  The picture overall lacks contrast.  Keep trying.</td>', 'I get the idea but the foreground is too washed out and the piano should have been dusted.  The picture overall lacks contrast.  Keep trying.', '2007-07-30 00:46:42.000000', NULL, 1),
(3947846, 558236, 58430, '<td valign="top">This is a wonderful waterfall picture.  For some reason the colors seem off like everything has a brown tinge.</td>', 'This is a wonderful waterfall picture.  For some reason the colors seem off like everything has a brown tinge.', '2007-07-30 00:47:28.000000', NULL, 1),
(3947847, 559203, 30982, '<td valign="top">Lovely macro - very nice take on the challenge.</td>', 'Lovely macro - very nice take on the challenge.', '2007-07-30 00:47:30.000000', NULL, 1),
(3947852, 557584, 58430, '<td valign="top">Nice effect.  How did you do this?</td>', 'Nice effect.  How did you do this?', '2007-07-30 00:48:08.000000', NULL, 1),
(3947858, 559124, 58430, '<td valign="top">I like the idea and the pattern but the image is way too grainy, oof and there are hotspots that really detract from this image.</td>', 'I like the idea and the pattern but the image is way too grainy, oof and there are hotspots that really detract from this image.', '2007-07-30 00:49:42.000000', NULL, 1),
(3947861, 558197, 58430, '<td valign="top">What is great portrait.  Love the chalk dust in the air and how the subject just pops from the background.</td>', 'What is great portrait.  Love the chalk dust in the air and how the subject just pops from the background.', '2007-07-30 00:50:34.000000', NULL, 1),
(3947863, 558962, 58430, '<td valign="top">Very colorful and definite rhythm.  The black in the upper right corner breaks that rhythm though.</td>', 'Very colorful and definite rhythm.  The black in the upper right corner breaks that rhythm though.', '2007-07-30 00:51:39.000000', NULL, 1),
