(3948601, 559008, 69368, '<td valign="top">Great shot, Sarah!<br/>congrats on the 6th!</td>', 'Great shot, Sarah!congrats on the 6th!', '2007-07-30 04:07:50.000000', NULL, 0),
(3948609, 559283, 39427, '<td valign="top">I really like what you''ve achieved here - I love the concept, the perspective, and the lens choice.  Regrettably tho, i have to agree with routerguy and confess that I wish the people were arranged differently.  I know you did not have infinite choice in the matter, i''m just saying that if I was a painter I would have done something different in the lower-left quadrant.  As it is though, the full outlines of the 2 couples there still  look awesome, great job!  Should have scored <i></i>way higher than it did.</td>', 'I really like what you''ve achieved here - I love the concept, the perspective, and the lens choice.  Regrettably tho, i have to agree with routerguy and confess that I wish the people were arranged differently.  I know you did not have infinite choice in the matter, i''m just saying that if I was a painter I would have done something different in the lower-left quadrant.  As it is though, the full outlines of the 2 couples there still  look awesome, great job!  Should have scored way higher than it did.', '2007-07-30 04:16:28.000000', NULL, 0),
(3948611, 556763, 31885, '<td valign="top">Wow, yet another brilliant image by the doc, congrats!</td>', 'Wow, yet another brilliant image by the doc, congrats!', '2007-07-30 04:17:57.000000', NULL, 0),
